import{_ as t,o as e,c as i,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2025-01-29","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2025-01-29","date":"2025-01-29T00:00:00.000Z","updated":"2025-02-27T00:00:00.000Z","tags":["Ceph","RGW","存储系统","竞态条件","多站点配置"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-01-29.md","filePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-01-29.md","lastUpdated":1780460162000}'),a={name:"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-01-29.md"};function n(r,l,s,p,c,g){return e(),i("div",null,[...l[0]||(l[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>: Ceph RGW对象删除问题讨论</p><p><strong>参会人员</strong>: Ceph开发团队成员</p><p><strong>会议时间</strong>: 2025年1月29日</p><h4 id="主要议题" tabindex="-1">主要议题: <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题:&quot;">​</a></h4><ol><li><p><strong>对象删除后残留问题</strong></p><ul><li><strong>问题描述</strong>: 用户在执行对象删除操作后，虽然返回状态码为0（成功），但在使用S3 API列出对象时，发现对象仍然存在。</li><li><strong>可能原因</strong>: <ul><li>删除操作与列出操作之间存在竞态条件。</li><li>删除操作可能在某些情况下被取消（e_cancel），导致索引条目未被删除。</li><li>索引池在高负载下可能出现延迟，导致删除操作未能及时更新索引。</li></ul></li><li><strong>讨论内容</strong>: <ul><li>开发人员讨论了删除操作的执行流程，特别是如何处理删除操作的返回码（如e_cancel）。</li><li>提出了在删除操作中考虑e_cancel的情况，并确保索引条目能够正确删除。</li><li>讨论了如何通过增加日志来更好地重现和定位问题。</li></ul></li></ul></li><li><p><strong>多站点配置下的Bucket删除问题</strong></p><ul><li><strong>问题描述</strong>: 在多站点配置下，删除Bucket后，Bucket仍然可以通过S3 API列出，但无法进行其他操作（如获取Bucket状态）。</li><li><strong>可能原因</strong>: <ul><li>Bucket的元数据（metadata）未被正确清理，导致用户空间中的omap条目仍然存在。</li><li>删除操作可能在后台超时或失败，导致Bucket未被正确清理。</li></ul></li><li><strong>讨论内容</strong>: <ul><li>讨论了如何通过手动清理用户空间中的omap条目来解决该问题。</li><li>提出了在删除Bucket后，重新创建同名Bucket并再次删除的方法，以覆盖omap条目。</li></ul></li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项: <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项:&quot;">​</a></h4><ol><li><p><strong>对象删除残留问题</strong>:</p><ul><li>需要进一步分析删除操作与列出操作之间的竞态条件，特别是e_cancel的情况。</li><li>开发人员计划增加日志以更好地重现和定位问题。</li><li>考虑在删除操作中自动修复残留对象的机制。</li></ul></li><li><p><strong>Bucket删除问题</strong>:</p><ul><li>需要进一步验证多站点配置下Bucket删除的清理机制。</li><li>考虑通过手动清理用户空间中的omap条目或重新创建同名Bucket来解决该问题。</li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划: <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划:&quot;">​</a></h4><ol><li><p><strong>对象删除残留问题</strong>:</p><ul><li>开发人员将增加日志并尝试重现问题。</li><li>讨论并实现e_cancel情况下的自动修复机制。</li></ul></li><li><p><strong>Bucket删除问题</strong>:</p><ul><li>验证多站点配置下Bucket删除的清理机制。</li><li>测试通过重新创建同名Bucket来清理omap条目的可行性。</li></ul></li></ol><p><strong>会议结束时间</strong>: 未知</p><p><strong>下次会议时间</strong>: 待定</p>',12)])])}const h=t(a,[["render",n]]);export{_ as __pageData,h as default};
